'use strict';

/**
 * Empreinte client cohérente (anti-détection / contournement CloudFront).
 *
 * POURQUOI CE MODULE
 * ------------------
 * Les logs montrent deux familles de refus distinctes :
 *   1. une page « 403 ERROR — Request blocked … Generated by cloudfront » :
 *      CloudFront refuse la REQUÊTE au niveau périphérique (WAF / bot control)
 *      AVANT même que Leboncoin ne réponde. Aucun CAPTCHA n'est affiché.
 *   2. un CAPTCHA / défi de vérification.
 *
 * Le point commun des deux : le client est reconnu comme un robot. Les causes
 * DÉMONTRABLES dans le code étaient :
 *   - un User-Agent annoncé (Chrome/122..125) INCOHÉRENT avec le moteur réel
 *     (Chromium 156) → « navigator.userAgent » mentait ;
 *   - aucun en-tête « Sec-CH-UA » alors que le navigateur est Chrome → un vrai
 *     Chrome envoie toujours ses client hints ; leur absence est un signal ;
 *   - en-têtes de navigation incomplets (pas d'Accept-Language, pas de
 *     Sec-Fetch-*, pas de Referer sur les fetch de détail) ;
 *   - fuites de l'automatisation : navigator.webdriver, plugins vides,
 *     navigator.languages incohérent, window.chrome absent, WebGL « SwiftShader ».
 *
 * Ce module centralise UNE empreinte cohérente (UA ↔ client hints ↔ JS) et un
 * script d'init appliqué à CHAQUE contexte Playwright (capture ET enrichissement).
 *
 * Aucune dépendance `electron` : importable par le pipeline forké.
 */

const fs = require('fs');
const path = require('path');

// ─────────────────────────────────────────────────────────────────────────────
// Version réelle du moteur Chromium embarqué (source de vérité de l'empreinte)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Lit la version majeure du Chromium réellement embarqué depuis `browsers.json`
 * de playwright-core. Aligner l'UA annoncé sur le moteur réel supprime la
 * incohérence UA ↔ comportement, qui est l'un des signaux anti-bot les plus
 * simples à exploiter.
 * @returns {string|null}
 */
function resolveChromiumMajorVersion() {
  try {
    // playwright-core expose browsers.json à la racine du paquet (pas de sous-export).
    const coreEntry = require.resolve('playwright-core');
    const browsersJson = path.join(path.dirname(coreEntry), 'browsers.json');
    const data = JSON.parse(fs.readFileSync(browsersJson, 'utf8'));
    const entry = (data.browsers || []).find((b) => b.name === 'chromium');
    if (entry && entry.browserVersion) return String(entry.browserVersion).split('.')[0];
  } catch { /* repli ci-dessous */ }
  return null;
}

const CHROMIUM_MAJOR = resolveChromiumMajorVersion();

function majorFromUserAgent(ua) {
  const m = /Chrome\/(\d+)/.exec(String(ua || ''));
  return m ? m[1] : null;
}

function platformFromUserAgent(ua) {
  const s = String(ua || '');
  if (/Windows NT/.test(s)) return { js: 'Win32', ch: 'Windows', platformVersion: '10.0.0' };
  if (/Macintosh/.test(s)) return { js: 'MacIntel', ch: 'macOS', platformVersion: '14.0.0' };
  return { js: 'Linux x86_64', ch: 'Linux', platformVersion: '6.0.0' };
}

// ─────────────────────────────────────────────────────────────────────────────
// En-têtes client
// ─────────────────────────────────────────────────────────────────────────────

const ACCEPT_NAVIGATION = 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8';
const ACCEPT_LANGUAGE = 'fr-FR,fr;q=0.9,en;q=0.8';

/**
 * Construit l'empreinte cohérente à partir d'un User-Agent (lequel doit être
 * celui réellement émis par le contexte Playwright).
 * @param {string} [userAgent]
 * @returns {{userAgent:string, majorVersion:string, platform:string, platformJs:string,
 *   locale:string, timezoneId:string, viewport:{width:number,height:number},
 *   secChUa:string, secChUaFullVersionList:string, extraHTTPHeaders:Object}}
 */
function createStealthProfile(userAgent) {
  const ua = String(userAgent || '').trim();
  const major = majorFromUserAgent(ua) || CHROMIUM_MAJOR || '125';
  const plat = platformFromUserAgent(ua);
  const brands = [
    { brand: 'Chromium', version: major },
    { brand: 'Google Chrome', version: major },
    { brand: 'Not:A-Brand', version: '24' },
  ];
  const secChUa = brands.map((b) => `"${b.brand}";v="${b.version}"`).join(', ');
  const secChUaFullVersionList = brands
    .map((b) => `"${b.brand}";v="${b.version}.0.0.0"`)
    .join(', ');

  return {
    userAgent: ua,
    majorVersion: major,
    platform: plat.ch,
    platformJs: plat.js,
    platformVersion: plat.platformVersion,
    locale: 'fr-FR',
    timezoneId: 'Europe/Paris',
    viewport: { width: 1366, height: 850 },
    secChUa,
    secChUaFullVersionList,
    // En-têtes envoyés sur TOUTE requête du contexte (navigation + sous-ressources).
    // On ne fixe PAS User-Agent ici (géré par contextOptions.userAgent), ni
    // Accept-Encoding (géré par Playwright — le fixer casserait la décompression),
    // ni `Accept` : l'imposer globalement ferait renvoyer du HTML aux appels XHR/API
    // JSON de la page (le `Accept` de navigation est réservé aux fetch de détail).
    // Accept-Language + client hints sont eux toujours présents chez un vrai Chrome.
    extraHTTPHeaders: {
      'Accept-Language': ACCEPT_LANGUAGE,
      'Sec-CH-UA': secChUa,
      'Sec-CH-UA-Mobile': '?0',
      'Sec-CH-UA-Platform': `"${plat.ch}"`,
      'Upgrade-Insecure-Requests': '1',
    },
  };
}

/**
 * En-têtes explicites pour un fetch de page de détail (enrichissement). Un vrai
 * navigateur émet `Sec-Fetch-*` et un `Referer` de recherche ; un fetch « nu »
 * ne les envoie pas → signal de robot. On reproduit ici la requête d'un clic.
 * @param {object} [profile]
 * @returns {Object}
 */
function clientHeadersFor(profile) {
  const p = profile || createStealthProfile();
  return {
    'Accept': ACCEPT_NAVIGATION,
    'Accept-Language': ACCEPT_LANGUAGE,
    'Sec-CH-UA': p.secChUa,
    'Sec-CH-UA-Mobile': '?0',
    'Sec-CH-UA-Platform': `"${p.platform}"`,
    'Upgrade-Insecure-Requests': '1',
    'Sec-Fetch-Dest': 'document',
    'Sec-Fetch-Mode': 'navigate',
    'Sec-Fetch-Site': 'same-origin',
    'Sec-Fetch-User': '?1',
    'Referer': 'https://www.leboncoin.fr/',
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Détection de la page de refus CloudFront / anti-bot (soft-block 200)
// ─────────────────────────────────────────────────────────────────────────────

// Marqueurs spécifiques de la page CloudFront « Request blocked ». Insensibles à
// la casse. Un marqueur suffit à classer la page comme refus d'accès, MÊME si le
// code HTTP est 200 (CloudFront sert souvent sa page d'erreur en 200/403).
const CLOUDFRONT_BLOCK_MARKERS = [
  'request blocked',
  'the request could not be satisfied',
  'generated by cloudfront',
  'cloudfront',
];

// Marqueurs de défi / refus plus larges (Datadome, Cloudflare, Arkose).
const ACCESS_BLOCK_MARKERS = [
  'captcha-delivery',
  'geo.captcha-delivery',
  'datadome',
  'unusual traffic',
  'are you human',
  'verify you are human',
  'checking your browser',
  'enable javascript and cookies to continue',
  'access denied',
];

/**
 * Détecte une page de refus CloudFront à partir de son HTML (ou texte).
 * @param {string} html
 * @returns {{blocked:boolean, marker:string|null, provider:string|null}}
 */
function detectCloudFrontBlock(html) {
  const text = String(html || '').toLowerCase();
  if (!text) return { blocked: false, marker: null, provider: null };
  const cf = CLOUDFRONT_BLOCK_MARKERS.find((m) => text.includes(m));
  if (cf) {
    // « cloudfront » seul est ambigu (peut apparaître dans du contenu légitime) :
    // on exige un marqueur fort, ou le couple « blocked/error » + cloudfront.
    const strong = cf !== 'cloudfront'
      || /(403|error|blocked|denied)/.test(text);
    if (strong) return { blocked: true, marker: cf, provider: 'cloudfront' };
  }
  const other = ACCESS_BLOCK_MARKERS.find((m) => text.includes(m));
  if (other) return { blocked: true, marker: other, provider: 'anti-bot' };
  return { blocked: false, marker: null, provider: null };
}

// ─────────────────────────────────────────────────────────────────────────────
// Script d'init anti-détection (appliqué à chaque contexte)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Script injecté AVANT tout script de page. Fonction AUTONOME (sérialisée par
 * Playwright) : elle ne peut référencer que `profile` (passé en argument).
 * Corrige les fuites d'automatisation les plus couramment testées.
 * @param {object} profile
 */
function stealthInitScript(profile) {
  try {
    const p = profile || {};
    const chromeMajor = String(p.majorVersion || '125');
    const defineGet = (obj, prop, getter) => {
      try { Object.defineProperty(obj, prop, { get: getter, configurable: true }); } catch (e) { /* ignore */ }
    };

    // 1. navigator.webdriver : absent chez un vrai utilisateur.
    defineGet(Navigator.prototype, 'webdriver', () => undefined);

    // 2. Langues cohérentes avec l'en-tête Accept-Language.
    defineGet(Navigator.prototype, 'languages', () => ['fr-FR', 'fr']);
    defineGet(Navigator.prototype, 'language', () => 'fr-FR');

    // 2b. navigator.platform cohérent avec l'OS annoncé dans le User-Agent.
    //     Sans cela, un UA « Windows » accompagné d'un navigator.platform
    //     « Linux x86_64 » est une incohérence triviale à détecter.
    defineGet(Navigator.prototype, 'platform', () => p.platformJs || 'Win32');

    // 3. Plugins + mimeTypes non vides (le headless les laisse vides).
    try {
      const mkPlugin = (name, filename, description) => ({
        name, filename, description, length: 1,
        item: () => null, namedItem: () => null,
      });
      const plugins = [
        mkPlugin('PDF Viewer', 'internal-pdf-viewer', 'Portable Document Format'),
        mkPlugin('Chrome PDF Viewer', 'internal-pdf-viewer', 'Portable Document Format'),
        mkPlugin('Chromium PDF Viewer', 'internal-pdf-viewer', 'Portable Document Format'),
      ];
      plugins.item = (i) => plugins[i] || null;
      plugins.namedItem = (n) => plugins.find((pl) => pl.name === n) || null;
      plugins.refresh = () => {};
      defineGet(Navigator.prototype, 'plugins', () => plugins);
    } catch (e) { /* ignore */ }

    // 4. window.chrome (absent en headless pur).
    try {
      if (!window.chrome) Object.defineProperty(window, 'chrome', { value: {}, configurable: true });
      const c = window.chrome;
      if (c && !c.runtime) Object.defineProperty(c, 'runtime', { value: {}, configurable: true });
      if (c && !c.app) {
        Object.defineProperty(c, 'app', {
          value: {
            isInstalled: false,
            InstallState: { DISABLED: 'disabled', INSTALLED: 'installed', NOT_INSTALLED: 'not_installed' },
            RunningState: { CANNOT_RUN: 'cannot_run', READY_TO_RUN: 'ready_to_run', RUNNING: 'running' },
          },
          configurable: true,
        });
      }
      if (c && !c.csi) Object.defineProperty(c, 'csi', { value: () => ({}), configurable: true });
      if (c && !c.loadTimes) Object.defineProperty(c, 'loadTimes', { value: () => ({}), configurable: true });
    } catch (e) { /* ignore */ }

    // 5. permissions.query('notifications') : état réel (headless renvoie 'denied').
    try {
      if (navigator.permissions && navigator.permissions.query) {
        const originalQuery = navigator.permissions.query.bind(navigator.permissions);
        defineGet(navigator.permissions, 'query', () => (params) => {
          try {
            if (params && params.name === 'notifications') {
              return Promise.resolve({ state: Notification.permission });
            }
          } catch (e) { /* ignore */ }
          return originalQuery(params);
        });
      }
    } catch (e) { /* ignore */ }

    // 6. UA-CH côté JS cohérent avec l'en-tête Sec-CH-UA.
    //    Le « headless shell » de Chromium n'expose PAS navigator.userAgentData ;
    //    l'installer (ou l'aligner) évite une empreinte incohérente : un client
    //    qui envoie Sec-CH-UA en en-tête mais n'a aucun userAgentData JS est
    //    immédiatement suspect. On construit un objet STABLE (même référence à
    //    chaque accès) avec les mêmes marques que l'en-tête.
    try {
      const brands = [
        { brand: 'Chromium', version: chromeMajor },
        { brand: 'Google Chrome', version: chromeMajor },
        { brand: 'Not:A-Brand', version: '24' },
      ];
      const full = brands.map((b) => ({ brand: b.brand, version: `${b.version}.0.0.0` }));
      const platName = p.platform || 'Windows';
      const uaData = {
        brands,
        mobile: false,
        platform: platName,
        getHighEntropyValues: () => Promise.resolve({
          brands,
          fullVersionList: full,
          platform: platName,
          platformVersion: p.platformVersion || '10.0.0',
          architecture: 'x86', bitness: '64', model: '',
          uaFullVersion: `${chromeMajor}.0.0.0`,
        }),
        toJSON: () => ({ brands, mobile: false, platform: platName }),
      };
      defineGet(Navigator.prototype, 'userAgentData', () => uaData);
    } catch (e) { /* ignore */ }

    // 7. WebGL : vendor/renderer crédibles (headless expose « SwiftShader »).
    try {
      const patch = (proto) => {
        if (!proto || !proto.getParameter) return;
        const orig = proto.getParameter;
        defineGet(proto, 'getParameter', () => function (param) {
          if (param === 37445) return 'Intel Inc.';
          if (param === 37446) return 'Intel Iris OpenGL Engine';
          return orig.call(this, param);
        });
      };
      if (typeof WebGLRenderingContext !== 'undefined') patch(WebGLRenderingContext.prototype);
      if (typeof WebGL2RenderingContext !== 'undefined') patch(WebGL2RenderingContext.prototype);
    } catch (e) { /* ignore */ }
  } catch (e) { /* jamais bloquant */ }
}

/**
 * Applique l'empreinte à un contexte Playwright : en-têtes client + script
 * d'init. Idempotent et best-effort (ne jette jamais : une empreinte
 * incomplète ne doit pas faire échouer la capture).
 * @param {import('playwright').BrowserContext} ctx
 * @param {object} [profile]
 * @returns {Promise<object>} le profil appliqué
 */
async function applyStealthToContext(ctx, profile) {
  const p = profile || createStealthProfile();
  try { await ctx.setExtraHTTPHeaders(p.extraHTTPHeaders); } catch (e) { /* best-effort */ }
  try { await ctx.addInitScript(stealthInitScript, p); } catch (e) { /* best-effort */ }
  return p;
}

module.exports = {
  resolveChromiumMajorVersion,
  createStealthProfile,
  clientHeadersFor,
  detectCloudFrontBlock,
  stealthInitScript,
  applyStealthToContext,
  CLOUDFRONT_BLOCK_MARKERS,
  ACCESS_BLOCK_MARKERS,
  ACCEPT_LANGUAGE,
  ACCEPT_NAVIGATION,
};
